const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))
const flag = n => ({Argentina:'🇦🇷',Brasil:'🇧🇷',Chile:'🇨🇱',Colômbia:'🇨🇴',Equador:'🇪🇨',Paraguai:'🇵🇾',Uruguai:'🇺🇾',Venezuela:'🇻🇪'})[n] || '⚽'
const teamName = id => state.teams.find(t => t.id === id)?.name || '—'
const playerName = id => { const p=state.players.find(p=>p.id===id); return p?.full_name || p?.name || '—' }
const playerPhoto = id => state.players.find(p=>p.id===id)?.photo_url || ''
const refereeName = id => state.referees.find(r=>r.id===id)?.name || '—'
const categoryLabel = c => ({ouro:'Ouro',prata:'Prata',diamante:'Diamante'})[c] || c || '—'
const criterionLabel = c => ({pontos:'Pontos',confronto_direto:'Confronto direto',saldo:'Saldo de gols',gols_marcados:'Gols marcados',gols_sofridos:'Gols sofridos'})[c] || c
const fmtDate = v => v ? new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}) : '—'
const canOperate = () => !!state.session && ['admin','organizador','arbitro','operador'].includes(state.profile?.role)
const roleLabel = r => ({admin:'Administrador',organizador:'Organizador',arbitro:'Árbitro',operador:'Operador',publico:'Público'})[r] || 'Público'

async function loadProfile(session){
  if(!session) return null
  const profileRes = await supabase.from('profiles').select('id,full_name,role,phone,created_at').eq('id', session.user.id).maybeSingle()
  if(profileRes.data) return profileRes.data
  const rpcRes = await supabase.rpc('get_my_profile')
  if(!rpcRes.error && Array.isArray(rpcRes.data) && rpcRes.data.length) return rpcRes.data[0]
  console.warn('Não foi possível carregar o perfil do usuário.', {
    userId: session.user.id,
    profileError: profileRes.error?.message || null,
    rpcError: rpcRes.error?.message || null
  })
  return null
}

async function load(){
  state.loading = true
  const sessionRes = await supabase.auth.getSession()
  state.session = sessionRes.data.session
  if(state.session){
    const userRes = await supabase.auth.getUser()
    if(userRes.error || !userRes.data.user){
      console.warn('Sessão inválida ou expirada.', userRes.error?.message || '')
      await supabase.auth.signOut()
      state.session = null
      state.profile = null
    } else {
      state.session = {...state.session, user:userRes.data.user}
      state.profile = await loadProfile(state.session)
    }
  } else state.profile = null
  const q = async t => (await supabase.from(t).select('*')).data || []
  state.competition = (await supabase.from('competitions').select('*').eq('name','2ª Copa das Nações Ouro/Prata/Diamante').maybeSingle()).data
  if(state.competition?.classification_criteria) state.classificationOrder = Array.isArray(state.competition.classification_criteria) ? state.competition.classification_criteria : state.classificationOrder
  ;[state.matches,state.teams,state.players,state.referees,state.groups,state.sponsors,state.media,state.allEvents] = await Promise.all(['matches','teams','players','referees','groups','sponsors','media_files'].map(q).concat([supabase.from('match_events').select('*').order('created_at',{ascending:true}).then(r=>r.data||[])]))
  state.matches.sort((a,b)=>new Date(a.scheduled_at||0)-new Date(b.scheduled_at||0))
  if(state.selectedMatch) await loadMatchDetails(state.selectedMatch.id, false)
  state.loading = false
  render()
}

async function loadMatchDetails(id, doRender=true){
  state.selectedMatch = state.matches.find(m=>m.id===id) || null
  if(!state.selectedMatch){ state.events=[]; state.lineups=[]; state.votes=[]; if(doRender) render(); return }
  const [ev,lu,v] = await Promise.all([
    supabase.from('match_events').select('*').eq('match_id',id).order('created_at',{ascending:true}),
    supabase.from('match_lineups').select('*').eq('match_id',id),
    supabase.from('match_votes').select('*').eq('match_id',id)
  ])
  state.events=ev.data||[]; state.lineups=lu.data||[]; state.votes=v.data||[]
  if(doRender) render()
}

function subscribe(){
  supabase.channel('futebol-campo-live')
    .on('postgres_changes',{event:'*',schema:'public',table:'matches'}, async payload=>{
      const i=state.matches.findIndex(x=>x.id===payload.new?.id)
      if(payload.eventType==='DELETE'){ if(i>=0) state.matches.splice(i,1) }
      else if(i>=0) state.matches[i]=payload.new; else state.matches.push(payload.new)
      if(state.selectedMatch?.id===payload.new?.id) await loadMatchDetails(payload.new.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_events'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_lineups'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    })
    .on('postgres_changes',{event:'*',schema:'public',table:'match_votes'}, async payload=>{
      if(state.selectedMatch?.id===payload.new?.match_id) await loadMatchDetails(state.selectedMatch.id,false)
      render()
    }).subscribe()
}

function nav(){return `<aside><div class="brand">⚽ <span>OURO & PRATA</span></div><nav>${[['dashboard','Painel','⌂'],['jogos','Jogos','▣'],['ao_vivo','Ao vivo','●'],['times','Times','◈'],['atletas','Atletas','♙'],['arbitragem','Arbitragem','⚑'],['grupos','Grupos','▦'],['classificacao','Classificação','☷'],['patrocinadores','Patrocinadores','★'],['midia','Fotos / Arquivos','▤'],['relatorios','Relatórios','▥']].map(x=>`<button class="${state.tab===x[0]?'active':''}" data-tab="${x[0]}"><i>${x[2]}</i><span>${x[1]}</span></button>`).join('')}</nav><div class="sidefoot">2ª Copa das Nações<br><small>Ouro • Prata • Diamante</small></div></aside>`}
function header(){return `<header><div><div class="eyebrow">GESTÃO ESPORTIVA • ONLINE</div><h1>${title()}</h1></div><div class="header-actions"><span class="pill">● ${state.session?'CONECTADO':'MODO PÚBLICO'}</span><button class="userbtn" id="authBtn">${state.session?`👤 ${esc(state.profile?.full_name||state.session.user.email)} · ${roleLabel(state.profile?.role)}`:'🔐 Entrar'}</button></div></header>`}
function title(){return ({dashboard:'Painel geral',jogos:'Jogos',ao_vivo:'Central ao vivo',times:'Times',atletas:'Atletas',arbitragem:'Arbitragem',grupos:'Classificação por grupo',classificacao:'Classificação geral',patrocinadores:'Patrocinadores',midia:'Fotos e arquivos',relatorios:'Relatórios'})[state.tab]}
function card(title,value,sub=''){return `<div class="card"><div class="muted">${title}</div><div class="big">${value}</div><div class="muted">${sub}</div></div>`}
function content(){
  if(state.tab==='dashboard') return `<section class="grid4">${card('Times',state.teams.length,'seleções cadastradas')}${card('Atletas',state.players.length,'cadastros')}${card('Árbitros',state.referees.length,'cadastros')}${card('Jogos',state.matches.length,'na competição')}</section><section class="panel hero"><div><span class="status">${state.competition?.status?.toUpperCase()||'ATIVA'}</span><h2>2ª Copa das Nações Ouro/Prata/Diamante</h2><p class="muted">Central profissional para jogos, súmulas, escalações, arbitragem, classificação e acompanhamento em tempo real.</p></div><div class="hero-score">${state.matches.filter(m=>m.status==='ao_vivo').length}<small>partidas ao vivo</small></div></section><section class="panel"><h2>Seleções</h2><div class="flags">${state.teams.map(t=>`<span>${flag(t.name)} ${esc(t.name)}</span>`).join('')}</div></section><section class="panel"><h2>Próximos jogos</h2>${matchesTable()}</section>`
  if(state.tab==='jogos') return gamesView()
  if(state.tab==='ao_vivo') return liveView()
  if(state.tab==='times') return list('Times',state.teams.map(t=>[flag(t.name)+' '+esc(t.name),t.country||'Seleção']), 'team')
  if(state.tab==='atletas') return list('Atletas',state.players.map(p=>[esc(p.full_name||p.name),(esc(teamName(p.team_id)))+' • '+esc(p.nickname||'')+' • '+esc(p.position||'')]), 'player')
  if(state.tab==='arbitragem') return list('Equipe de arbitragem',state.referees.map(r=>[esc(r.name),esc(r.role||r.registration||'Árbitro')]), 'referee')
  if(state.tab==='grupos') return groupSettingsView()
  if(state.tab==='classificacao') return classificationView()
  if(state.tab==='patrocinadores') return sponsorsView()
  if(state.tab==='midia') return mediaView()
  if(state.tab==='relatorios') return reportsView()
}
function gamesView(){return `<section class="panel"><div class="panelhead"><div><h2>Calendário e partidas</h2><p class="muted">Partidas agendadas, em andamento e encerradas.</p></div>${canOperate()?'<button class="primary" data-crud="match">+ Novo jogo</button>':''}</div>${matchesTable(true)}</section>`}
function matchStatusLabel(status){return status==='agendado'?'PARTIDA NÃO INICIADA':status==='ao_vivo'?'AO VIVO':status==='encerrado'?'ENCERRADA':status.toUpperCase()}
function matchesTable(selectable=false){
  if(!state.matches.length)return `<div class="empty">Nenhum jogo cadastrado ainda.</div>`;
  return `<div class="tablewrap"><table><tr><th>Data</th><th>Jogo</th><th>Placar</th><th>Status</th>${selectable?'<th>Arbitragem</th><th>Ações</th>':''}</tr>${state.matches.map(m=>{
    const h=teamName(m.home_team_id),a=teamName(m.away_team_id);
    const actions=selectable&&canOperate()?`${m.status==='encerrado'?`<button class="smallbtn" data-reopen-match="${m.id}">↩ Reabrir</button>`:`<button class="smallbtn" data-edit-crud="match" data-id="${m.id}">✏️ Alterar</button>`}<button class="smallbtn" data-open-match="${m.id}">Abrir</button>`:'';
    const officials=selectable?`<div><b>Árbitro:</b> ${esc(refereeName(m.referee_id))}<br><b>Assist. 1:</b> ${esc(refereeName(m.assistant_1_id))}<br><b>Assist. 2:</b> ${esc(refereeName(m.assistant_2_id))}<br><b>Mesário:</b> ${esc(refereeName(m.fourth_official_id))}</div>`:'';
    return `<tr><td>${fmtDate(m.scheduled_at)}</td><td>${flag(h)} <b>${esc(h)}</b> × <b>${esc(a)}</b> ${flag(a)}</td><td><b>${m.home_score||0} × ${m.away_score||0}</b></td><td><span class="tag ${m.status}">${matchStatusLabel(m.status)}</span></td>${selectable?`<td>${officials}</td><td>${actions}</td>`:''}</tr>`
  }).join('')}</table></div>`
}
function calcStandings(teamIds=null, options={}){
  const ids=teamIds||state.teams.map(t=>t.id);
  const rows=state.teams.filter(t=>ids.includes(t.id)).map(t=>({team:t,j:0,v:0,e:0,d:0,gp:0,gc:0,pts:0,directPts:0}));
  const map=new Map(rows.map(r=>[r.team.id,r]));
  const games=state.matches.filter(m=>m.status==='encerrado'&&map.has(m.home_team_id)&&map.has(m.away_team_id));
  games.forEach(m=>{const h=map.get(m.home_team_id),a=map.get(m.away_team_id);h.j++;a.j++;h.gp+=m.home_score||0;h.gc+=m.away_score||0;a.gp+=m.away_score||0;a.gc+=m.home_score||0;if((m.home_score||0)>(m.away_score||0)){h.v++;h.pts+=3;a.d++}else if((m.home_score||0)<(m.away_score||0)){a.v++;a.pts+=3;h.d++}else{h.e++;a.e++;h.pts++;a.pts++}});
  // Confronto direto: calculado entre equipes que terminaram empatadas em pontos.
  const byPts={}; rows.forEach(r=>(byPts[r.pts]??=[]).push(r.team.id));
  Object.values(byPts).filter(ids2=>ids2.length>1).forEach(ids2=>{
    games.filter(m=>ids2.includes(m.home_team_id)&&ids2.includes(m.away_team_id)).forEach(m=>{
      if((m.home_score||0)>(m.away_score||0)) map.get(m.home_team_id).directPts+=3;
      else if((m.home_score||0)<(m.away_score||0)) map.get(m.away_team_id).directPts+=3;
      else {map.get(m.home_team_id).directPts++;map.get(m.away_team_id).directPts++}
    })
  });
  const order=options.order||state.classificationOrder;
  const cmp=(a,b,c)=>{if(c==='pontos')return b.pts-a.pts;if(c==='confronto_direto')return b.directPts-a.directPts;if(c==='saldo')return (b.gp-b.gc)-(a.gp-a.gc);if(c==='gols_marcados')return b.gp-a.gp;if(c==='gols_sofridos')return a.gc-b.gc;return 0};
  rows.sort((a,b)=>{for(const c of order){const d=cmp(a,b,c);if(d)return d}return a.team.name.localeCompare(b.team.name)});
  return rows;
}
function standingsTable(rows, showDirect=false){return `<div class="tablewrap"><table><tr><th>#</th><th>Equipe</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th>${showDirect?'<th>CD</th>':''}<th>Pts</th></tr>${rows.map((r,i)=>`<tr><td><b>${i+1}</b></td><td>${flag(r.team.name)} ${esc(r.team.name)}</td><td>${r.j}</td><td>${r.v}</td><td>${r.e}</td><td>${r.d}</td><td>${r.gp}</td><td>${r.gc}</td><td>${r.gp-r.gc}</td>${showDirect?`<td>${r.directPts}</td>`:''}<td><b>${r.pts}</b></td></tr>`).join('')}</table></div>`}
function groupStandingsView(){const groups=state.groups.slice().sort((a,b)=>a.position-b.position);return `<section class="panel"><div class="panelhead"><div><h2>Classificação por grupo</h2><p class="muted">${state.competition?.group_count||groups.length} grupos • critérios: ${state.classificationOrder.map(criterionLabel).join(' → ')}</p></div></div>${groups.map(g=>{const teams=state.teams.filter(t=>t.group_id===g.id);return `<div class="panel"><h3>${esc(g.name)}</h3>${teams.length?standingsTable(calcStandings(teams.map(t=>t.id),{order:state.classificationOrder}),true):'<div class="empty">Nenhuma equipe neste grupo.</div>'}</div>`}).join('')}</section>`}
function sponsorsView(){return `<section class="panel"><div class="panelhead"><div><h2>Patrocinadores</h2><p class="muted">Parceiros oficiais da competição.</p></div>${canOperate()?'<button class="primary" data-sponsor-new>+ Incluir patrocinador</button>':''}</div><div class="flags">${state.sponsors.filter(s=>s.active).sort((a,b)=>a.sort_order-b.sort_order).map(s=>`<div class="sponsor-card">${s.logo_url?`<img src="${esc(s.logo_url)}" alt="${esc(s.name)}">`:'🏢'}<b>${esc(s.name)}</b>${s.website?`<a href="${esc(s.website)}" target="_blank">Site</a>`:''}${canOperate()?`<button class="smallbtn" data-sponsor-edit="${s.id}">Alterar</button><button class="smallbtn" data-sponsor-delete="${s.id}">Excluir</button>`:''}</div>`).join('')}</div></section>`}
function mediaView(){const photos=state.media.filter(x=>x.category==='foto'),videos=state.media.filter(x=>x.category==='video'),files=state.media.filter(x=>!['foto','video'].includes(x.category));return `<section class="panel"><div class="panelhead"><div><h2>Fotos / Arquivos / Vídeos</h2><p class="muted">Biblioteca oficial da Copa.</p></div>${canOperate()?'<button class="primary" data-media-new>+ Adicionar foto, arquivo ou vídeo</button>':''}</div><h3>Fotos</h3><div class="media-grid">${photos.length?photos.map(mediaCard).join(''):'<div class="empty">Nenhuma foto cadastrada.</div>'}</div><h3>Vídeos</h3><div class="media-grid">${videos.length?videos.map(mediaCard).join(''):'<div class="empty">Nenhum vídeo cadastrado.</div>'}</div><h3>Arquivos</h3><div class="media-list">${files.length?files.map(mediaCard).join(''):'<div class="empty">Nenhum arquivo cadastrado.</div>'}</div></section>`}
function mediaCard(x){return `<div class="media-card">${x.category==='foto'||x.mime_type?.startsWith('image/')?`<img src="${esc(x.file_url)}" alt="${esc(x.title)}">`:x.category==='video'||x.mime_type?.startsWith('video/')?`<video controls preload="metadata" src="${esc(x.file_url)}"></video>`:'📄'}<b>${esc(x.title)}</b><a class="smallbtn" href="${esc(x.file_url)}" target="_blank">Abrir / baixar</a>${canOperate()?`<button class="smallbtn" data-media-delete="${x.id}">Excluir</button>`:''}</div>`}
function reportsView(){return `<section class="panel"><div class="panelhead"><div><h2>Relatórios</h2><p class="muted">Escolha um relatório e imprima ou salve em PDF pelo navegador.</p></div></div><div class="report-buttons">${['jogos','atletas','atletas_equipe','artilheiros','equipes','cartoes','classificacao','grupos'].map(x=>`<button class="secondary" data-report="${x}">${({jogos:'Jogos',atletas:'Atletas',atletas_equipe:'Atletas por equipe',artilheiros:'Artilheiros',equipes:'Equipes',cartoes:'Cartões',classificacao:'Classificação geral',grupos:'Classificação por grupos'})[x]}</button>`).join('')}</div>${state.reportType?reportContent(state.reportType):'<div class="empty">Selecione um relatório.</div>'}</section>`}
function reportContent(type){let title=({jogos:'Relatório de jogos',atletas:'Relatório de atletas',atletas_equipe:'Atletas por equipe',artilheiros:'Artilharia',equipes:'Relatório de equipes',cartoes:'Cartões',classificacao:'Classificação geral',grupos:'Classificação por grupos'})[type];let body='';if(type==='jogos')body=matchesTable(false);if(type==='atletas')body=`<div class="tablewrap"><table><tr><th>Atleta</th><th>Apelido</th><th>Equipe</th><th>Categoria</th><th>Nascimento</th><th>Posição</th><th>Nº</th></tr>${state.players.map(p=>`<tr><td>${esc(p.full_name||p.name)}</td><td>${esc(p.nickname||'')}</td><td>${esc(teamName(p.team_id))}</td><td>${esc(categoryLabel(p.category))}</td><td>${p.birth_date?new Date(p.birth_date+'T00:00:00').toLocaleDateString('pt-BR'):''}</td><td>${esc(p.position||'')}</td><td>${p.shirt_number||''}</td></tr>`).join('')}</table></div>`;if(type==='atletas_equipe')body=state.teams.map(t=>`<div class="panel"><h3>${flag(t.name)} ${esc(t.name)}</h3><div class="tablewrap"><table><tr><th>#</th><th>Atleta</th><th>Apelido</th><th>Categoria</th><th>Posição</th><th>Nº</th></tr>${state.players.filter(p=>p.team_id===t.id).sort((a,b)=>(a.full_name||a.name).localeCompare(b.full_name||b.name)).map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.full_name||p.name)}</td><td>${esc(p.nickname||'')}</td><td>${esc(categoryLabel(p.category))}</td><td>${esc(p.position||'')}</td><td>${p.shirt_number||''}</td></tr>`).join('')}</table></div></div>`).join('');if(type==='equipes')body=`<div class="tablewrap"><table><tr><th>Equipe</th><th>Grupo</th></tr>${state.teams.map(t=>`<tr><td>${flag(t.name)} ${esc(t.name)}</td><td>${esc(state.groups.find(g=>g.id===t.group_id)?.name||'—')}</td></tr>`).join('')}</table></div>`;if(type==='artilheiros'){const map={};state.allEvents.filter(e=>e.type==='gol'&&e.player_id).forEach(e=>map[e.player_id]=(map[e.player_id]||0)+1);body=`<div class="tablewrap"><table><tr><th>#</th><th>Atleta</th><th>Equipe</th><th>Gols</th></tr>${Object.entries(map).sort((a,b)=>b[1]-a[1]).map(([id,n],i)=>`<tr><td>${i+1}</td><td>${esc(playerName(id))}</td><td>${esc(teamName(state.players.find(p=>p.id===id)?.team_id))}</td><td><b>${n}</b></td></tr>`).join('')}</table></div>`}if(type==='cartoes'){const map={};state.allEvents.filter(e=>['cartao_amarelo','cartao_vermelho'].includes(e.type)&&e.player_id).forEach(e=>{const k=e.player_id+'|'+e.type;map[k]=(map[k]||0)+1});body=`<div class="tablewrap"><table><tr><th>Atleta</th><th>Equipe</th><th>Tipo</th><th>Quantidade</th></tr>${Object.entries(map).map(([k,n])=>{const [id,t]=k.split('|');return `<tr><td>${esc(playerName(id))}</td><td>${esc(teamName(state.players.find(p=>p.id===id)?.team_id))}</td><td>${t==='cartao_amarelo'?'Amarelo':'Vermelho'}</td><td>${n}</td></tr>`}).join('')}</table></div>`}if(type==='classificacao')body=standingsTable(calcStandings(null,{order:state.classificationOrder}),false);if(type==='grupos')body=state.groups.slice().sort((a,b)=>a.position-b.position).map(g=>`<h3>${esc(g.name)}</h3>${standingsTable(calcStandings(state.teams.filter(t=>t.group_id===g.id).map(t=>t.id),{order:state.classificationOrder}),true)}`).join('');return `<div class="report-preview"><div class="panelhead"><h3>${title}</h3><button class="primary" data-print-report>🖨️ Imprimir / PDF</button></div>${body}</div>`}
function matchCard(m){const h=teamName(m.home_team_id),a=teamName(m.away_team_id);return `<div class="matchmini"><div>${flag(h)} <b>${esc(h)}</b></div><div class="scoremini">${m.home_score}<span>×</span>${m.away_score}</div><div><b>${esc(a)}</b> ${flag(a)}</div><button class="smallbtn" data-open-match="${m.id}">Súmula</button></div>`}
function liveSheet(){const m=state.selectedMatch;if(!m)return '';return `<div class="live-sheet"><div class="sheet-head"><div><span class="status">${m.reopened_at&&m.status==='agendado'?'REABERTA':m.status.toUpperCase()}</span><h2>${flag(teamName(m.home_team_id))} ${esc(teamName(m.home_team_id))} <strong>${m.home_score} × ${m.away_score}</strong> ${esc(teamName(m.away_team_id))} ${flag(teamName(m.away_team_id))}</h2><p class="muted">${fmtDate(m.scheduled_at)} • ${esc(m.field_name||'Campo não informado')}</p></div><div class="clock"><div id="matchClock">${matchClock(m)}</div><small>${state.timerHalf==='2T'?'2º TEMPO':state.timerHalf==='1T'?'1º TEMPO':m.status==='encerrado'?'ENCERRADO':'PARADO'}</small></div></div>${controlBar(m)}${correctionPanel(m)}<div class="sheet-grid"><div class="sheet-main">${eventPanel(m)}${eventTimeline()}</div><div class="sheet-side">${lineupPanel(m)}${votePanel(m)}</div></div></div>`}
function matchClock(m){let base=0, started=state.timerStartedAt, half=state.timerHalf;if(half==='1T'){base=m.first_half_elapsed_seconds||0;started=started||m.first_half_started_at}else if(half==='2T'){base=m.second_half_elapsed_seconds||0;started=started||m.second_half_started_at}if(!started)return fmtSec(base);return fmtSec(base+Math.max(0,Math.floor((Date.now()-new Date(started).getTime())/1000)))}
function fmtSec(s){const min=Math.floor(s/60),sec=s%60;return String(min).padStart(2,'0')+':'+String(sec).padStart(2,'0')}
function controlBar(m){const disabled=!canOperate()||m.status==='encerrado';return `<div class="controlbar"><button class="primary" ${disabled?'disabled':''} data-action="start1">▶ Iniciar 1º tempo</button><button ${disabled?'disabled':''} data-action="start2">▶ Iniciar 2º tempo</button><button ${disabled?'disabled':''} data-action="pause">⏸ Pausar</button><button class="danger" ${disabled?'disabled':''} data-action="finish">■ Encerrar partida</button><label>Acréscimos 1T <input id="add1" type="number" min="0" value="${m.added_time_first_half||0}"></label><label>2T <input id="add2" type="number" min="0" value="${m.added_time_second_half||0}"></label></div>`}
function correctionPanel(m){if(!canOperate()||!m.reopened_at||m.status!=='agendado')return '';return `<div class="panel correction"><div class="panelhead"><div><h3>🔧 Correção da partida</h3><p class="muted">Partida reaberta. Você pode corrigir o resultado e os eventos.</p></div></div><div class="eventform"><label>Placar ${esc(teamName(m.home_team_id))}<input id="corrHome" type="number" min="0" value="${m.home_score||0}"></label><label>Placar ${esc(teamName(m.away_team_id))}<input id="corrAway" type="number" min="0" value="${m.away_score||0}"></label><button class="primary" data-action="saveScoreCorrection">💾 Salvar resultado</button></div></div>`}
function eventPanel(m){const home=state.players.filter(p=>p.team_id===m.home_team_id),away=state.players.filter(p=>p.team_id===m.away_team_id);const players=home.concat(away);return `<div class="eventpanel"><div class="panelhead"><h3>Registrar ocorrência</h3><span class="muted">${state.events.length} eventos</span></div>${!canOperate()?'<div class="notice">🔒 Faça login com perfil de administrador, organizador, árbitro ou operador para registrar ocorrências.</div>':''}<div class="eventform"><select id="eventType"><option value="gol">⚽ Gol</option><option value="cartao_amarelo">🟨 Cartão amarelo</option><option value="cartao_vermelho">🟥 Cartão vermelho</option><option value="substituicao">🔄 Substituição</option><option value="incidente">📝 Incidente</option></select><select id="eventTeam"><option value="">Equipe</option><option value="${m.home_team_id}">${esc(teamName(m.home_team_id))}</option><option value="${m.away_team_id}">${esc(teamName(m.away_team_id))}</option></select><select id="eventPlayer"><option value="">Atleta</option>${players.map(p=>`<option value="${p.id}">${esc(p.name)} — ${esc(teamName(p.team_id))}</option>`).join('')}</select><input id="eventMinute" type="number" min="0" max="150" placeholder="Min." value="${currentMinute()}"/><input id="eventAdded" type="number" min="0" max="20" placeholder="+"/><input id="eventDesc" placeholder="Observação"/><button class="primary" ${!canOperate()?'disabled':''} data-action="event">Registrar</button></div><div class="subform"><select id="subOut"><option value="">Sai</option>${players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><select id="subIn"><option value="">Entra</option>${players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button class="secondary" ${!canOperate()?'disabled':''} data-action="sub">Registrar substituição</button></div></div>`}
function currentMinute(){if(!state.timerStartedAt)return 0;return Math.floor((Date.now()-new Date(state.timerStartedAt).getTime())/60000)}
function eventTimeline(){const editable=canOperate()&&state.selectedMatch?.reopened_at&&state.selectedMatch?.status==='agendado';return `<div class="timeline"><h3>Eventos da partida</h3>${state.events.length?state.events.slice().reverse().map(e=>`<div class="eventrow"><span class="eventicon">${eventIcon(e.type)}</span><div><b>${esc(eventLabel(e.type))}</b> <span class="muted">${e.minute??'—'}${e.added_minute?`+${e.added_minute}`:''}'</span><div>${e.player_id?esc(playerName(e.player_id)):''}${e.related_player_id?` → ${esc(playerName(e.related_player_id))}`:''}</div><small>${esc(e.description||'')}</small></div><span class="muted">${esc(teamName(e.team_id))}${editable?` <button class="smallbtn" data-event-edit="${e.id}">✏️</button><button class="smallbtn" data-event-delete="${e.id}">🗑️</button>`:''}</span></div>`).join(''):`<div class="empty">Nenhuma ocorrência registrada.</div>`}</div>`}
function eventIcon(t){return {gol:'⚽',cartao_amarelo:'🟨',cartao_vermelho:'🟥',substituicao:'🔄',incidente:'📝'}[t]||'•'}
function eventLabel(t){return {gol:'Gol',cartao_amarelo:'Cartão amarelo',cartao_vermelho:'Cartão vermelho',substituicao:'Substituição',incidente:'Incidente'}[t]||t}
function lineupPanel(m){const teamBlocks=[m.home_team_id,m.away_team_id].map(tid=>{const ps=state.players.filter(p=>p.team_id===tid);return `<div class="lineupteam"><h4>${flag(teamName(tid))} ${esc(teamName(tid))}</h4>${ps.length?ps.map(p=>{const l=state.lineups.find(x=>x.player_id===p.id);const st=l?.status||'reserva';return `<label class="playerline"><span>${p.shirt_number?`#${p.shirt_number} `:''}${esc(p.name)}</span><select data-lineup-status="${p.id}" ${!canOperate()?'disabled':''}><option value="titular" ${st==='titular'?'selected':''}>Titular</option><option value="reserva" ${st==='reserva'?'selected':''}>Reserva</option><option value="nao_compareceu" ${st==='nao_compareceu'?'selected':''}>Não compareceu</option></select></label>`}).join(''):'<div class="muted">Nenhum atleta cadastrado.</div>'}</div>`}).join('');return `<div class="lineuppanel"><div class="panelhead"><h3>Súmula / escalação</h3><button class="secondary" data-action="saveLineup" ${!canOperate()?'disabled':''}>Salvar situação dos atletas</button></div><p class="muted">Informe Titular, Reserva ou Não compareceu.</p>${teamBlocks}</div>`}
function votePanel(m){const candidates=state.players.filter(p=>state.lineups.some(l=>l.match_id===m.id&&l.player_id===p.id&&l.status==='titular'));const counts=state.votes.reduce((a,v)=>(a[v.player_id]=(a[v.player_id]||0)+1,a),{});return `<div class="votepanel"><h3>Melhor jogador da partida</h3>${candidates.length?candidates.sort((a,b)=>(counts[b.id]||0)-(counts[a.id]||0)).map(p=>`<button class="vote" data-vote="${p.id}" ${!state.session?'disabled':''}>⭐ ${esc(p.name)} <b>${counts[p.id]||0}</b></button>`).join(''):'<div class="muted">Defina a escalação titular para liberar os candidatos.</div>'}</div>`}
function standingsView(){return `<section class="panel"><div class="panelhead"><div><h2>Classificação geral</h2><p class="muted">Selecione qual classificação deseja visualizar.</p></div></div><div class="report-buttons"><button class="${state.classificationView==='grupo'?'primary':'secondary'}" data-classification="grupo">📊 Classificação por grupo</button><button class="${state.classificationView==='geral'?'primary':'secondary'}" data-classification="geral">🌎 Classificação geral</button><button class="secondary" data-criteria-order>⚙️ Alterar ordem dos critérios</button></div>${state.classificationView==='grupo'?groupStandingsView():`<div class="panel"><p class="muted">Critérios: ${state.classificationOrder.map(criterionLabel).join(' → ')}</p>${standingsTable(calcStandings(null,{order:state.classificationOrder}),false)}</div>`}</section>`}
function classificationView(){return standingsView()}
function criteriaModal(){const items=[...state.classificationOrder];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="criteriaModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">CLASSIFICAÇÃO</div><h2>Ordem dos critérios</h2><p class="muted">Use ↑ e ↓ para definir a prioridade.</p><div id="criteriaList">${items.map((c,i)=>`<div class="criterion-row" data-criterion="${c}"><b>${i+1}. ${criterionLabel(c)}</b><span><button class="smallbtn" data-criterion-up="${c}">↑</button><button class="smallbtn" data-criterion-down="${c}">↓</button></span></div>`).join('')}</div><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-save-criteria>Salvar ordem</button></div></div></div>`)}
async function saveCriteriaOrder(){if(!canOperate())return;const order=[...document.querySelectorAll('#criteriaList [data-criterion]')].map(x=>x.dataset.criterion);const {error}=await supabase.from('competitions').update({classification_criteria:order}).eq('id',state.competition.id);if(error)return toast(error.message,'error');state.classificationOrder=order;state.competition.classification_criteria=order;document.querySelector('#criteriaModal')?.remove();render();toast('Ordem dos critérios salva.')} 
function groupSettingsView(){const groups=state.groups.slice().sort((a,b)=>a.position-b.position);const phases=Array.isArray(state.competition?.phases)?state.competition.phases:[];return `<section class="panel"><div class="panelhead"><div><h2>Grupos e fases</h2><p class="muted">Configure quantidade de grupos e as fases do campeonato.</p></div>${canOperate()?'<button class="primary" data-structure-settings>⚙️ Configurar campeonato</button>':''}</div><div class="cards">${card('Quantidade de grupos',state.competition?.group_count||groups.length,'grupos configurados')}${card('Fases',phases.length||1,'etapas do campeonato')}</div><div class="panel"><h3>Grupos cadastrados</h3>${groups.map(g=>`<div class="flags"><span><b>${esc(g.name)}</b> • ${state.teams.filter(t=>t.group_id===g.id).length} equipes</span></div>`).join('')}</div><div class="panel"><h3>Fases</h3>${phases.length?phases.map((p,i)=>`<div class="flags"><span>${i+1}. ${esc(p.name||'Fase')} — <b>${p.type==='mata_mata'?'Mata-mata':'Classificatória'}</b></span></div>`).join(''):'<div class="empty">Nenhuma fase configurada.</div>'}</section>`}
function structureModal(){const count=Number(state.competition?.group_count||state.groups.length||2);const phases=Array.isArray(state.competition?.phases)&&state.competition.phases.length?state.competition.phases:[{name:'Classificatória',type:'classificatoria'}];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="structureModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">CAMPEONATO</div><h2>Configurar grupos e fases</h2><label>Quantidade de grupos<select id="groupCount">${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===count?'selected':''}>${n}</option>`).join('')}</select></label><h3>Fases</h3><div id="phaseRows">${phases.map((p,i)=>`<div class="phase-row"><input data-phase-name value="${esc(p.name||'')}" placeholder="Nome da fase"><select data-phase-type><option value="classificatoria" ${p.type==='classificatoria'?'selected':''}>Classificatória</option><option value="mata_mata" ${p.type==='mata_mata'?'selected':''}>Mata-mata</option></select><button class="smallbtn" data-remove-phase>Excluir</button></div>`).join('')}</div><button class="secondary" data-add-phase>+ Adicionar fase</button><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-save-structure>Salvar configuração</button></div></div></div>`)}
async function saveStructure(){if(!canOperate())return;const count=Number(document.querySelector('#groupCount').value);const phases=[...document.querySelectorAll('.phase-row')].map(r=>({name:r.querySelector('[data-phase-name]').value.trim()||'Fase',type:r.querySelector('[data-phase-type]').value}));if(!phases.length)return toast('Inclua pelo menos uma fase.','error');const oldGroups=state.groups.slice().sort((a,b)=>a.position-b.position);const teamsOutside=oldGroups.slice(count).some(g=>state.teams.some(t=>t.group_id===g.id));if(teamsOutside)return toast('Não é possível reduzir a quantidade de grupos enquanto houver equipes nos grupos que serão removidos.','error');const {error}=await supabase.from('competitions').update({group_count:count,phases}).eq('id',state.competition.id);if(error)return toast(error.message,'error');for(let i=1;i<=count;i++){if(!oldGroups[i-1]){const ins=await supabase.from('groups').insert({competition_id:state.competition.id,name:`Grupo ${String.fromCharCode(64+i)}`,position:i});if(ins.error)return toast(ins.error.message,'error')}}if(oldGroups.length>count){const ids=oldGroups.slice(count).map(g=>g.id);await supabase.from('groups').delete().in('id',ids)}document.querySelector('#structureModal')?.remove();await load();toast('Configuração do campeonato salva.')}
function list(title,items,type){const data=type==='team'?state.teams:type==='player'?state.players:type==='referee'?state.referees:[];const rows=data.map(r=>{const label=type==='team'?flag(r.name)+' '+esc(r.name):type==='player'?`${r.photo_url?`<img class="avatar" src="${esc(r.photo_url)}">`:''}${esc(r.full_name||r.name)}`:esc(r.name);const detail=type==='team'?esc(r.country||'Seleção'):type==='player'?`${esc(teamName(r.team_id))} • ${esc(r.nickname||'')} • ${esc(categoryLabel(r.category))} • ${esc(r.position||'')}`:esc(r.role||r.registration||'Árbitro');return `<tr><td><b>${label}</b></td><td>${detail}</td>${canOperate()?`<td class="actions"><button class="smallbtn" data-edit-crud="${type}" data-id="${r.id}">✏️ Alterar</button><button class="danger smallbtn" data-delete-crud="${type}" data-id="${r.id}">🗑️ Excluir</button></td>`:''}</tr>`}).join('');return `<section class="panel"><div class="panelhead"><h2>${title}</h2><div class="panelhead"><span class="tag">${items.length} registros</span>${canOperate()&&type?`<button class="primary" data-crud="${type}">➕ Incluir</button>`:''}</div></div>${data.length?`<div class="tablewrap"><table><tr><th>Nome</th><th>Detalhes</th>${canOperate()?'<th>Ações</th>':''}</tr>${rows}</table></div>`:`<div class="empty">Nenhum registro cadastrado.</div>`}</section>`}

async function updateMatch(values){if(!canOperate()||!state.selectedMatch)return toast('Acesso operacional necessário.','error');const {error}=await supabase.from('matches').update(values).eq('id',state.selectedMatch.id);if(error)return toast(error.message,'error');await load();}
async function startHalf(half){if(!canOperate())return toast('Entre com perfil autorizado.','error');const m=state.selectedMatch;if(!m)return;const now=new Date().toISOString();state.timerHalf=half;state.timerStartedAt=now;const values=half==='1T'?{status:'ao_vivo',first_half_started_at:now}:{status:'ao_vivo',second_half_started_at:now};await updateMatch(values);startTicker()}
async function pause(){if(!canOperate()||!state.selectedMatch)return;const m=state.selectedMatch;if(!state.timerStartedAt){stopTicker();return}const elapsed=Math.max(0,Math.floor((Date.now()-new Date(state.timerStartedAt).getTime())/1000));const field=state.timerHalf==='2T'?'second_half_elapsed_seconds':'first_half_elapsed_seconds';const values={[field]:(m[field]||0)+elapsed};state.timerStartedAt=null;stopTicker();await updateMatch(values);state.timerHalf=null;toast('Cronômetro pausado e tempo salvo.');}
async function finishMatch(){if(!canOperate())return toast('Entre com perfil autorizado.','error');if(!confirm('Encerrar esta partida e confirmar o placar?'))return;if(state.timerStartedAt)await pause();await updateMatch({status:'encerrado',finished_at:new Date().toISOString()});state.timerStartedAt=null;stopTicker();state.timerHalf=null;await loadMatchDetails(state.selectedMatch.id,false);render()}
async function addEvent(){if(!canOperate())return toast('Acesso operacional necessário.','error');const m=state.selectedMatch;if(!m)return;const type=document.querySelector('#eventType')?.value,team_id=document.querySelector('#eventTeam')?.value||null,player_id=document.querySelector('#eventPlayer')?.value||null,minute=Number(document.querySelector('#eventMinute')?.value)||0,added_minute=Number(document.querySelector('#eventAdded')?.value)||0,description=document.querySelector('#eventDesc')?.value||null;if(type!=='incidente'&&!team_id)return toast('Selecione a equipe.','error');if(type!=='incidente'&&!player_id)return toast('Selecione o atleta.','error');if(type==='substituicao')return toast('Use o formulário específico de substituição.','error');const {error}=await supabase.from('match_events').insert({match_id:m.id,team_id,player_id,minute,added_minute,description,type,created_by:state.session.user.id});if(error)return toast(error.message,'error');if(type==='gol'){const field=team_id===m.home_team_id?'home_score':'away_score';await supabase.from('matches').update({[field]:(m[field]||0)+1}).eq('id',m.id)}await loadMatchDetails(m.id,false);await load();}
async function addSub(){if(!canOperate())return toast('Acesso operacional necessário.','error');const m=state.selectedMatch;const out=document.querySelector('#subOut')?.value,inP=document.querySelector('#subIn')?.value,team_id=out?state.players.find(p=>p.id===out)?.team_id:null;if(!out||!inP||!team_id)return toast('Informe quem sai e quem entra.','error');const minute=Number(document.querySelector('#eventMinute')?.value)||currentMinute();const {error}=await supabase.from('match_events').insert({match_id:m.id,team_id,player_id:out,related_player_id:inP,minute,type:'substituicao',description:`Substituição: ${playerName(out)} por ${playerName(inP)}`,created_by:state.session.user.id});if(error)return toast(error.message,'error');await loadMatchDetails(m.id);}
async function saveLineup(){if(!canOperate())return toast('Acesso operacional necessário.','error');const m=state.selectedMatch;const selects=[...document.querySelectorAll('[data-lineup-status]')];const rows=selects.map((b,i)=>({match_id:m.id,player_id:b.dataset.lineupStatus,status:b.value,starter_position:b.value==='titular'?i+1:null}));await supabase.from('match_lineups').delete().eq('match_id',m.id);const {error}=rows.length?await supabase.from('match_lineups').insert(rows):{error:null};if(error)return toast(error.message,'error');await loadMatchDetails(m.id);toast('Situação dos atletas salva.');}
async function vote(player_id){if(!state.session)return openAuth();const {error}=await supabase.from('match_votes').insert({match_id:state.selectedMatch.id,player_id,voter_id:state.session.user.id,vote_type:'melhor_jogador'});if(error)return toast(error.message,'error');toast('Voto registrado.','ok');}
async function reopenMatch(id){if(!canOperate())return;const ok=await askConfirm('Reabrir esta partida para correção? O placar e os eventos serão preservados.');if(!ok)return;const {error}=await supabase.from('matches').update({status:'agendado',finished_at:null,reopened_at:new Date().toISOString(),reopened_by:state.session.user.id}).eq('id',id);if(error)return toast(error.message,'error');toast('Partida reaberta. Agora você pode alterar resultado e eventos.');await load();}
async function saveScoreCorrection(){if(!canOperate())return;const m=state.selectedMatch;if(!m?.reopened_at)return toast('Reabra a partida antes de corrigir o resultado.','error');const home=Math.max(0,Number(document.querySelector('#corrHome')?.value)||0),away=Math.max(0,Number(document.querySelector('#corrAway')?.value)||0);const {error}=await supabase.from('matches').update({home_score:home,away_score:away}).eq('id',m.id);if(error)return toast(error.message,'error');await loadMatchDetails(m.id,false);await load();toast('Resultado corrigido.');}
function eventEditModal(id){const e=state.events.find(x=>x.id===id),m=state.selectedMatch;if(!e||!m)return;const players=state.players.filter(p=>p.team_id===m.home_team_id||p.team_id===m.away_team_id);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="eventEditModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">CORRIGIR EVENTO</div><h2>${esc(eventLabel(e.type))}</h2><select id="eeType"><option value="gol" ${e.type==='gol'?'selected':''}>⚽ Gol</option><option value="cartao_amarelo" ${e.type==='cartao_amarelo'?'selected':''}>🟨 Cartão amarelo</option><option value="cartao_vermelho" ${e.type==='cartao_vermelho'?'selected':''}>🟥 Cartão vermelho</option><option value="incidente" ${e.type==='incidente'?'selected':''}>📝 Incidente</option></select><select id="eeTeam"><option value="">Equipe</option><option value="${m.home_team_id}" ${e.team_id===m.home_team_id?'selected':''}>${esc(teamName(m.home_team_id))}</option><option value="${m.away_team_id}" ${e.team_id===m.away_team_id?'selected':''}>${esc(teamName(m.away_team_id))}</option></select><select id="eePlayer"><option value="">Atleta</option>${players.map(p=>`<option value="${p.id}" ${e.player_id===p.id?'selected':''}>${esc(p.name)} — ${esc(teamName(p.team_id))}</option>`).join('')}</select><input id="eeMinute" type="number" min="0" max="150" value="${e.minute??0}"><input id="eeAdded" type="number" min="0" max="20" value="${e.added_minute??0}"><input id="eeDesc" value="${esc(e.description||'')}" placeholder="Observação"><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-event-update="${id}">💾 Salvar correção</button></div></div></div>`)}
async function updateEvent(id){if(!canOperate())return;const m=state.selectedMatch,e=state.events.find(x=>x.id===id);if(!m?.reopened_at||!e)return;const type=document.querySelector('#eeType').value,team_id=document.querySelector('#eeTeam').value||null,player_id=document.querySelector('#eePlayer').value||null,minute=Math.max(0,Number(document.querySelector('#eeMinute').value)||0),added_minute=Math.max(0,Number(document.querySelector('#eeAdded').value)||0),description=document.querySelector('#eeDesc').value.trim()||null;const {error}=await supabase.from('match_events').update({type,team_id,player_id,minute,added_minute,description}).eq('id',id);if(error)return toast(error.message,'error');document.querySelector('#eventEditModal')?.remove();await loadMatchDetails(m.id,false);toast('Evento corrigido.');}
async function deleteEvent(id){if(!canOperate())return;const m=state.selectedMatch;if(!m?.reopened_at)return;const ok=await askConfirm('Excluir este evento?');if(!ok)return;const e=state.events.find(x=>x.id===id);const {error}=await supabase.from('match_events').delete().eq('id',id);if(error)return toast(error.message,'error');if(e?.type==='gol'){const {data}=await supabase.from('match_events').select('team_id').eq('match_id',m.id).eq('type','gol');const home=(data||[]).filter(x=>x.team_id===m.home_team_id).length,away=(data||[]).filter(x=>x.team_id===m.away_team_id).length;await supabase.from('matches').update({home_score:home,away_score:away}).eq('id',m.id)}await loadMatchDetails(m.id,false);await load();toast('Evento excluído.');}
async function markNotStarted(id){if(!canOperate())return;const {error}=await supabase.from('matches').update({status:'agendado'}).eq('id',id);if(error)return toast(error.message,'error');toast('Partida marcada como não iniciada.');await load();}
function sponsorModal(id=null){const c=id?state.sponsors.find(x=>x.id===id):null;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="sponsorModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">PATROCINADOR</div><h2>${c?'Alterar':'Novo'} patrocinador</h2><input id="spName" value="${esc(c?.name||'')}" placeholder="Nome"><input id="spLogo" value="${esc(c?.logo_url||'')}" placeholder="URL da logo (opcional)"><label>Baixar/inserir arquivo da logomarca<input id="spLogoFile" type="file" accept="image/*"></label>${c?.logo_url?`<img class="athlete-photo-preview" src="${esc(c.logo_url)}" alt="Logo atual">`:''}<input id="spSite" value="${esc(c?.website||'')}" placeholder="Site"><input id="spContact" value="${esc(c?.contact||'')}" placeholder="Contato"><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-sponsor-save="${id||''}">Salvar</button></div></div></div>`)}
async function saveSponsor(id=''){if(!canOperate())return;const row={competition_id:state.competition.id,name:document.querySelector('#spName').value.trim(),logo_url:document.querySelector('#spLogo').value.trim()||null,website:document.querySelector('#spSite').value.trim()||null,contact:document.querySelector('#spContact').value.trim()||null};if(!row.name)return toast('Informe o nome.','error');const file=document.querySelector('#spLogoFile')?.files?.[0];if(file){const old=state.sponsors.find(s=>s.id===id);if(old?.logo_path)await supabase.storage.from('ouro-prata-arquivos').remove([old.logo_path]);const path=`${state.competition.id}/patrocinadores/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('ouro-prata-arquivos').upload(path,file,{upsert:false});if(up.error)return toast(up.error.message,'error');row.logo_path=path;row.logo_url=supabase.storage.from('ouro-prata-arquivos').getPublicUrl(path).data.publicUrl}const res=id?await supabase.from('sponsors').update(row).eq('id',id):await supabase.from('sponsors').insert(row);if(res.error)return toast(res.error.message,'error');document.querySelector('#sponsorModal')?.remove();await load();toast('Patrocinador salvo.')}
async function deleteSponsor(id){if(!(await askConfirm('Excluir este patrocinador?')))return;const {error}=await supabase.from('sponsors').delete().eq('id',id);if(error)return toast(error.message,'error');await load();}
function mediaModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="mediaModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">BIBLIOTECA</div><h2>Adicionar foto, vídeo ou arquivo</h2><input id="mdTitle" placeholder="Título"><select id="mdCategory"><option value="foto">Foto</option><option value="video">Vídeo</option><option value="arquivo">Arquivo</option><option value="documento">Documento</option></select><input id="mdFile" type="file" accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx"><input id="mdDesc" placeholder="Descrição"><div class="modal-actions"><button class="secondary" data-close>Cancelar</button><button class="primary" data-media-save>Enviar</button></div></div></div>`)}
async function saveMedia(){const file=document.querySelector('#mdFile')?.files?.[0];const title=document.querySelector('#mdTitle').value.trim()||file?.name;if(!file||!title)return toast('Escolha um arquivo e informe o título.','error');const path=`${state.competition.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('ouro-prata-arquivos').upload(path,file,{upsert:false});if(up.error)return toast(up.error.message,'error');const pub=supabase.storage.from('ouro-prata-arquivos').getPublicUrl(path).data.publicUrl;const ins=await supabase.from('media_files').insert({competition_id:state.competition.id,title,category:document.querySelector('#mdCategory').value,file_url:pub,storage_path:path,mime_type:file.type||null,description:document.querySelector('#mdDesc').value.trim()||null});if(ins.error)return toast(ins.error.message,'error');document.querySelector('#mediaModal')?.remove();await load();toast('Arquivo enviado.');}
async function deleteMedia(id){const x=state.media.find(m=>m.id===id);if(!(await askConfirm('Excluir este arquivo?')))return;if(x?.storage_path)await supabase.storage.from('ouro-prata-arquivos').remove([x.storage_path]);const {error}=await supabase.from('media_files').delete().eq('id',id);if(error)return toast(error.message,'error');await load();}
function crudModal(type,id=null){
  if(!canOperate()) return;
  const current=id?(type==='team'?state.teams:type==='player'?state.players:type==='referee'?state.referees:state.matches).find(x=>x.id===id):null;
  const common=`<button class="close" data-close>×</button><div class="eyebrow">${current?'ALTERAR':'INCLUIR'} CADASTRO</div>`;
  const val=(key='')=>esc(current?.[key]??''); let body='';
  if(type==='team') body=`${common}<h2>${current?'Alterar time':'Novo time'}</h2><input id="fName" value="${val('name')}" placeholder="Nome do time" required><input id="fCountry" value="${val('country')}" placeholder="País / seleção"><select id="fGroup"><option value="">Sem grupo</option>${state.groups.slice().sort((a,b)=>a.position-b.position).map(g=>`<option value="${g.id}" ${current?.group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><div class="modal-actions"><button class="secondary" data-close>❌ Cancelar</button><button class="primary" data-save-crud="team" data-id="${id||''}">💾 Salvar</button></div>`;
  if(type==='player') body=`${common}<h2>${current?'Alterar atleta':'Novo atleta'}</h2><label>Nome completo<input id="fName" value="${val('full_name')||val('name')}" placeholder="Nome completo" required></label><label>Apelido<input id="fNickname" value="${val('nickname')}" placeholder="Apelido"></label><label>Data de nascimento<input id="fBirthDate" type="date" value="${val('birth_date')}"></label><label>Equipe<select id="fTeam">${state.teams.map(t=>`<option value="${t.id}" ${current?.team_id===t.id?'selected':''}>${flag(t.name)} ${esc(t.name)}</option>`).join('')}</select></label><label>Categoria<select id="fCategory"><option value="ouro" ${current?.category==='ouro'?'selected':''}>Ouro</option><option value="prata" ${current?.category==='prata'?'selected':''}>Prata</option><option value="diamante" ${current?.category==='diamante'?'selected':''}>Diamante</option></select></label><label>Posição<select id="fPosition"><option value="">Selecione</option>${['Goleiro','Lateral Direito','Lateral Esquerdo','Zagueiro','Meio-Campo','Atacante'].map(x=>`<option ${current?.position===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Número<input id="fNumber" type="number" min="1" max="99" value="${current?.shirt_number??''}" placeholder="Número"></label><label>Foto do atleta<input id="fPhoto" type="file" accept="image/*"></label>${current?.photo_url?`<img class="athlete-photo-preview" src="${esc(current.photo_url)}" alt="Foto atual">`:''}<div class="modal-actions"><button class="secondary" data-close>❌ Cancelar</button><button class="primary" data-save-crud="player" data-id="${id||''}">💾 Salvar</button></div>`;
  if(type==='referee') body=`${common}<h2>${current?'Alterar integrante':'Novo integrante'}</h2><input id="fName" value="${val('name')}" placeholder="Nome completo" required><select id="fRefRole"><option value="arbitro" ${current?.role==='arbitro'?'selected':''}>Árbitro</option><option value="assistente" ${current?.role==='assistente'?'selected':''}>Assistente</option><option value="mesario" ${current?.role==='mesario'?'selected':''}>Mesário</option></select><input id="fReg" value="${val('registration')}" placeholder="Registro"><input id="fPhone" value="${val('phone')}" placeholder="Telefone"><div class="modal-actions"><button class="secondary" data-close>❌ Cancelar</button><button class="primary" data-save-crud="referee" data-id="${id||''}">💾 Salvar</button></div>`;
  if(type==='match') body=`${common}<h2>${current?'Alterar jogo':'Novo jogo'}</h2><label>Mandante<select id="fHome">${state.teams.map(t=>`<option value="${t.id}" ${current?.home_team_id===t.id?'selected':''}>${flag(t.name)} ${esc(t.name)}</option>`).join('')}</select></label><label>Visitante<select id="fAway">${state.teams.map(t=>`<option value="${t.id}" ${current?.away_team_id===t.id?'selected':''}>${flag(t.name)} ${esc(t.name)}</option>`).join('')}</select></label><label>Grupo<select id="fMatchGroup"><option value="">Sem grupo</option>${state.groups.slice().sort((a,b)=>a.position-b.position).map(g=>`<option value="${g.id}" ${current?.group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>Árbitro<select id="fRef"><option value="">Sem árbitro</option>${state.referees.map(r=>`<option value="${r.id}" ${current?.referee_id===r.id?'selected':''}>${esc(r.name)} — ${esc(r.role||'Árbitro')}</option>`).join('')}</select></label><label>Assistente 1<select id="fAssistant1"><option value="">Não definido</option>${state.referees.map(r=>`<option value="${r.id}" ${current?.assistant_1_id===r.id?'selected':''}>${esc(r.name)} — ${esc(r.role||'Assistente')}</option>`).join('')}</select></label><label>Assistente 2<select id="fAssistant2"><option value="">Não definido</option>${state.referees.map(r=>`<option value="${r.id}" ${current?.assistant_2_id===r.id?'selected':''}>${esc(r.name)} — ${esc(r.role||'Assistente')}</option>`).join('')}</select></label><label>Mesário<select id="fMesario"><option value="">Não definido</option>${state.referees.map(r=>`<option value="${r.id}" ${current?.fourth_official_id===r.id?'selected':''}>${esc(r.name)} — ${esc(r.role||'Mesário')}</option>`).join('')}</select></label><label>Data e hora<input id="fDate" type="datetime-local" value="${current?.scheduled_at?new Date(current.scheduled_at).toISOString().slice(0,16):''}"></label><input id="fField" value="${val('field_name')}" placeholder="Campo"><div class="modal-actions"><button class="secondary" data-close>❌ Cancelar</button><button class="primary" data-save-crud="match" data-id="${id||''}">💾 Salvar</button></div>`;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="crudModal"><div class="modalbox">${body}</div></div>`);
  const modal=document.querySelector('#crudModal'); modal?.querySelectorAll('[data-close]').forEach(btn=>btn.addEventListener('click',()=>modal.remove())); const saveBtn=modal?.querySelector('[data-save-crud]'); if(saveBtn)saveBtn.addEventListener('click',()=>saveCrud(saveBtn.dataset.saveCrud,saveBtn.dataset.id||''));
}
async function saveCrud(type,id=''){
  if(!canOperate())return; let row={};
  if(type==='team') row={competition_id:state.competition.id,name:document.querySelector('#fName').value.trim(),country:document.querySelector('#fCountry').value.trim()||null,group_id:document.querySelector('#fGroup').value||null};
  if(type==='player'){
    const fullName=document.querySelector('#fName').value.trim(); if(!fullName)return toast('Informe o nome completo.','error');
    row={team_id:document.querySelector('#fTeam').value,name:fullName,full_name:fullName,nickname:document.querySelector('#fNickname').value.trim()||null,birth_date:document.querySelector('#fBirthDate').value||null,category:document.querySelector('#fCategory').value,shirt_number:Number(document.querySelector('#fNumber').value)||null,position:document.querySelector('#fPosition').value||null};
    const file=document.querySelector('#fPhoto')?.files?.[0];
    if(file){const old=state.players.find(p=>p.id===id);if(old?.photo_path)await supabase.storage.from('ouro-prata-arquivos').remove([old.photo_path]);const path=`${state.competition.id}/atletas/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('ouro-prata-arquivos').upload(path,file,{upsert:false});if(up.error)return toast(up.error.message,'error');row.photo_path=path;row.photo_url=supabase.storage.from('ouro-prata-arquivos').getPublicUrl(path).data.publicUrl}
  }
  if(type==='referee') row={name:document.querySelector('#fName').value.trim(),role:document.querySelector('#fRefRole').value,registration:document.querySelector('#fReg').value.trim()||null,phone:document.querySelector('#fPhone').value.trim()||null};
  if(type==='match'){const h=document.querySelector('#fHome').value,a=document.querySelector('#fAway').value;if(h===a)return toast('O mandante e o visitante devem ser diferentes.','error');const dt=document.querySelector('#fDate').value;row={competition_id:state.competition.id,group_id:document.querySelector('#fMatchGroup').value||null,home_team_id:h,away_team_id:a,referee_id:document.querySelector('#fRef').value||null,assistant_1_id:document.querySelector('#fAssistant1').value||null,assistant_2_id:document.querySelector('#fAssistant2').value||null,fourth_official_id:document.querySelector('#fMesario').value||null,scheduled_at:dt?new Date(dt).toISOString():null,field_name:document.querySelector('#fField').value.trim()||null}};
  if(!row.name&&['team','player','referee'].includes(type))return toast('Informe o nome.','error'); const table={team:'teams',player:'players',referee:'referees',match:'matches'}[type]; const answer=await askConfirm(id?'Confirma ALTERAR este cadastro?':'Confirma SALVAR este cadastro?');if(!answer)return;const result=id?await supabase.from(table).update(row).eq('id',id):await supabase.from(table).insert(row);if(result.error)return toast(result.error.message,'error');document.querySelector('#crudModal')?.remove();toast(id?'Cadastro alterado com sucesso.':'Cadastro salvo com sucesso.');await load();
}
async function deleteCrud(type,id){
  if(!canOperate())return;
  const table={team:'teams',player:'players',referee:'referees',match:'matches'}[type];
  const label=type==='team'?teamName(id):type==='player'?playerName(id):type==='referee'?(state.referees.find(x=>x.id===id)?.name||'este árbitro'):'este jogo';
  const ok=await askConfirm(`Deseja EXCLUIR ${label}? Esta ação não pode ser desfeita.`); if(!ok)return;
  const {error}=await supabase.from(table).delete().eq('id',id);if(error)return toast(error.message,'error');toast('Cadastro excluído com sucesso.');await load();
}
function askConfirm(message){return new Promise(resolve=>{const old=document.querySelector('#confirmModal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="confirmModal"><div class="modalbox"><div class="eyebrow">CONFIRMAÇÃO</div><h2>Confirmação</h2><p>${esc(message)}</p><div class="modal-actions"><button class="secondary" id="confirmNo">NÃO</button><button class="danger" id="confirmYes">SIM</button></div></div></div>`);document.querySelector('#confirmNo').onclick=()=>{document.querySelector('#confirmModal')?.remove();resolve(false)};document.querySelector('#confirmYes').onclick=()=>{document.querySelector('#confirmModal')?.remove();resolve(true)}})}

async function authSubmit(){const email=document.querySelector('#authEmail')?.value.trim(),password=document.querySelector('#authPassword')?.value;if(!email||!password)return toast('Informe e-mail e senha.','error');let res;if(state.authMode==='signup')res=await supabase.auth.signUp({email,password});else res=await supabase.auth.signInWithPassword({email,password});if(res.error)return toast(res.error.message,'error');if(state.authMode==='signup')toast('Usuário criado. Se a confirmação de e-mail estiver ativa, confirme o e-mail antes de entrar.','ok');else toast('Login realizado.','ok');await load();}
async function logout(){await supabase.auth.signOut();state.session=null;state.profile=null;render()}
function openAuth(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="authModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">ACESSO AO SISTEMA</div><h2>${state.authMode==='signup'?'Criar usuário':'Entrar'}</h2><p class="muted">Para operar a súmula, use um usuário com perfil autorizado no Supabase.</p><input id="authEmail" type="email" placeholder="E-mail"><input id="authPassword" type="password" placeholder="Senha"><button class="primary wide" data-auth-submit>${state.authMode==='signup'?'Criar usuário':'Entrar'}</button><button class="linkbtn" data-toggle-auth>${state.authMode==='signup'?'Já tenho cadastro':'Criar novo usuário'}</button></div></div>`)}
function toast(msg,type='ok'){document.querySelectorAll('.toast').forEach(x=>x.remove());document.body.insertAdjacentHTML('beforeend',`<div class="toast ${type}">${esc(msg)}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),3500)}
function startTicker(){stopTicker();state.timerInterval=setInterval(()=>{const el=document.querySelector('#matchClock');if(el)el.textContent=matchClock(state.selectedMatch)},1000)}
function stopTicker(){if(state.timerInterval)clearInterval(state.timerInterval);state.timerInterval=null}

function render(){app.innerHTML=`<div class="layout">${nav()}<main>${header()}${state.loading?'<section class="panel"><div class="empty">Carregando dados...</div></section>':content()}</main></div>`;bind();if(state.timerStartedAt)startTicker()}

function moveCriterion(c,delta){const a=[...document.querySelectorAll('#criteriaList [data-criterion]')].map(x=>x.dataset.criterion);const i=a.indexOf(c),j=i+delta;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];const box=document.querySelector('#criteriaList');box.innerHTML=a.map((x,k)=>`<div class="criterion-row" data-criterion="${x}"><b>${k+1}. ${criterionLabel(x)}</b><span><button class="smallbtn" data-criterion-up="${x}">↑</button><button class="smallbtn" data-criterion-down="${x}">↓</button></span></div>`).join('');box.querySelectorAll('[data-criterion-up]').forEach(b=>b.onclick=()=>moveCriterion(b.dataset.criterion,-1));box.querySelectorAll('[data-criterion-down]').forEach(b=>b.onclick=()=>moveCriterion(b.dataset.criterion,1))}
function addPhaseRow(){const box=document.querySelector('#phaseRows');if(!box)return;box.insertAdjacentHTML('beforeend',`<div class="phase-row"><input data-phase-name value="" placeholder="Nome da fase"><select data-phase-type><option value="classificatoria">Classificatória</option><option value="mata_mata">Mata-mata</option></select><button class="smallbtn" data-remove-phase>Excluir</button></div>`);box.lastElementChild.querySelector('[data-remove-phase]').onclick=()=>box.lastElementChild.remove()}
function liveView(){return `<section class="panel"><div class="panelhead"><div><h2>Central ao vivo / Súmula</h2><p class="muted">Selecione uma partida para abrir a súmula completa.</p></div>${state.selectedMatch?`<button class="secondary" data-back-games>← Voltar aos jogos</button>`:''}</div>${state.selectedMatch?liveSheet():`<div class="grid4">${state.matches.map(matchCard).join('')}</div>`}</section>`}
function bind(){
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.reportType=null;render()});
  document.querySelectorAll('[data-open-match]').forEach(b=>b.onclick=async()=>{state.tab='ao_vivo';state.selectedMatch=null;await loadMatchDetails(b.dataset.openMatch);});
  document.querySelectorAll('[data-crud]').forEach(b=>b.onclick=()=>crudModal(b.dataset.crud));document.querySelectorAll('[data-edit-crud]').forEach(b=>b.onclick=()=>crudModal(b.dataset.editCrud,b.dataset.id));document.querySelectorAll('[data-delete-crud]').forEach(b=>b.onclick=()=>deleteCrud(b.dataset.deleteCrud,b.dataset.id));document.querySelectorAll('[data-save-crud]').forEach(b=>b.onclick=()=>saveCrud(b.dataset.saveCrud,b.dataset.id));
  document.querySelector('#authBtn')?.addEventListener('click',()=>state.session?openUserMenu():openAuth());
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='start1')await startHalf('1T');if(a==='start2')await startHalf('2T');if(a==='pause')await pause();if(a==='finish')await finishMatch();if(a==='event')await addEvent();if(a==='sub')await addSub();if(a==='saveLineup')await saveLineup();if(a==='saveScoreCorrection')await saveScoreCorrection()});
  document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>vote(b.dataset.vote));document.querySelectorAll('[data-reopen-match]').forEach(b=>b.onclick=()=>reopenMatch(b.dataset.reopenMatch));document.querySelectorAll('[data-not-started]').forEach(b=>b.onclick=()=>markNotStarted(b.dataset.notStarted));
  document.querySelectorAll('[data-sponsor-new]').forEach(b=>b.onclick=()=>sponsorModal());document.querySelectorAll('[data-sponsor-edit]').forEach(b=>b.onclick=()=>sponsorModal(b.dataset.sponsorEdit));document.querySelectorAll('[data-sponsor-delete]').forEach(b=>b.onclick=()=>deleteSponsor(b.dataset.sponsorDelete));document.querySelectorAll('[data-media-new]').forEach(b=>b.onclick=()=>mediaModal());document.querySelectorAll('[data-media-delete]').forEach(b=>b.onclick=()=>deleteMedia(b.dataset.mediaDelete));
  document.querySelectorAll('[data-event-edit]').forEach(b=>b.onclick=()=>eventEditModal(b.dataset.eventEdit));document.querySelectorAll('[data-event-delete]').forEach(b=>b.onclick=()=>deleteEvent(b.dataset.eventDelete));document.querySelectorAll('[data-event-update]').forEach(b=>b.onclick=()=>updateEvent(b.dataset.eventUpdate));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{state.reportType=b.dataset.report;render()});document.querySelector('[data-print-report]')?.addEventListener('click',()=>window.print());
  document.querySelectorAll('[data-classification]').forEach(b=>b.onclick=()=>{state.classificationView=b.dataset.classification;render()});document.querySelector('[data-criteria-order]')?.addEventListener('click',criteriaModal);document.querySelector('[data-save-criteria]')?.addEventListener('click',saveCriteriaOrder);document.querySelectorAll('[data-criterion-up]').forEach(b=>b.onclick=()=>moveCriterion(b.dataset.criterion,-1));document.querySelectorAll('[data-criterion-down]').forEach(b=>b.onclick=()=>moveCriterion(b.dataset.criterion,1));
  document.querySelector('[data-back-games]')?.addEventListener('click',()=>{state.tab='jogos';state.selectedMatch=null;render()});document.querySelector('[data-structure-settings]')?.addEventListener('click',structureModal);document.querySelector('[data-add-phase]')?.addEventListener('click',addPhaseRow);document.querySelectorAll('[data-remove-phase]').forEach(b=>b.onclick=()=>b.closest('.phase-row')?.remove());document.querySelector('[data-save-structure]')?.addEventListener('click',saveStructure);
  document.querySelector('[data-sponsor-save]')?.addEventListener('click',e=>saveSponsor(e.target.dataset.sponsorSave||''));document.querySelector('[data-media-save]')?.addEventListener('click',saveMedia)
}
function openUserMenu(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="userModal"><div class="modalbox"><button class="close" data-close>×</button><div class="eyebrow">USUÁRIO</div><h2>${esc(state.profile?.full_name||state.session.user.email)}</h2><p>Perfil: <b>${roleLabel(state.profile?.role)}</b></p><button class="danger wide" id="logoutBtn">Sair</button></div></div>`);document.querySelector('#logoutBtn').onclick=logout}
document.addEventListener('click',e=>{if(e.target.matches('[data-close]'))e.target.closest('.modal')?.remove();if(e.target.matches('[data-auth-submit]'))authSubmit();if(e.target.matches('[data-sponsor-save]'))saveSponsor(e.target.dataset.sponsorSave||'');if(e.target.matches('[data-media-save]'))saveMedia();if(e.target.matches('[data-toggle-auth]')){state.authMode=state.authMode==='login'?'signup':'login';document.querySelector('#authModal')?.remove();openAuth()}})

supabase.auth.onAuthStateChange(async()=>{setTimeout(load,0)})
subscribe()
load()
